import json, numpy as np
from PIL import Image
meta=json.load(open('/app/runs/initial/meta.json'))['cameras']
Tbase=np.eye(4); Tbase[:3,:3]=[[0,-1,0],[1,0,0],[0,0,1]]; Tbase[:3,3]=[2.67,-2.17004,.91472]
def points(cam, mask):
 c=meta[cam]; K=np.array(c['intrinsic_cv']); T=np.array(c['cam2world_gl']); im=np.array(Image.open(f'/app/runs/initial/last/{cam}.jpg').convert('RGB')); d=np.load(f'/app/runs/initial/depth_{cam}.npy').squeeze(); ys,xs=np.where(mask & (d>0));
 # camera coordinates GL
 z=-d[ys,xs]; x=(xs-K[0,2])*d[ys,xs]/K[0,0]; y=-(ys-K[1,2])*d[ys,xs]/K[1,1]; xyz=np.stack([x,y,z,np.ones(len(z))],1); w=(T@xyz.T).T[:,:3]; b=((np.linalg.inv(Tbase)@np.c_[w,np.ones(len(w))].T).T)[:,:3]
 return w,b,d[ys,xs],np.stack([xs,ys],1)
for cam,rect in [('egoview',(172,202,173,204)),('robot0_eye_in_right_hand',(0,110,215,239)),('egoview',(255,319,125,215)),('robot0_agentview_right',(203,250,143,205))]:
