 w,b,d,uv=points(cam,m)
 print('\n',cam,rect,'n=',len(d))
 for label,a in [('depth',d),('uv',uv),('world',w),('base',b)]: print(label, 'med',np.round(np.median(a,axis=0),3),'p10',np.round(np.percentile(a,10,axis=0),3),'p90',np.round(np.percentile(a,90,axis=0),3))
